#!/usr/bin/env bash
# Build the gcc host harness for the Duke DI kernel.
# sh_params.h is generated by the real build tool (zd2_make_effect.py runs it
# before the TI cl6x step); a copy lives in embedded/effects/duke/build/.
set -euo pipefail
here="$(cd "$(dirname "$0")" && pwd)"
root="$(cd "$here/.." && pwd)"
eff="$root/embedded/effects/duke"
out="$here/host_duke"
cc="${CC:-gcc}"
"$cc" -O2 -std=c99 -Wall -Wextra -Wno-unused-parameter \
  -I"$eff/build" -I"$eff" \
  "$here/host_main.c" "$eff/duke.c" "$eff/tables_data.c" \
  -lm -o "$out"
echo "built $out"
